@@ -0,0 +1,40 @@
+package main
+
+import (
+	"fmt"
+	"regexp"
+	"time"
+)
+
+// Simulating the old approach (recompiling regex every time)
+func oldApproach(pattern, input string, iterations int) time.Duration {
+	start := time.Now()
+	for i := 0; i < iterations; i++ {
+		rx := regexp.MustCompile("^" + pattern + "$")
+		rx.MatchString(input)
+	}
+	return time.Since(start)
+}
+
+// Simulating the new approach (pre-compiling regex)
+func newApproach(pattern, input string, iterations int) time.Duration {
+	rx := regexp.MustCompile("^" + pattern + "$")
+	start := time.Now()
+	for i := 0; i < iterations; i++ {
+		rx.MatchString(input)
+	}
+	return time.Since(start)
+}
+
+func main() {
+	pattern := `\d{5}(-\d{4})?`
+	input := "12345-6789"
+	iterations := 10000
+
+	oldTime := oldApproach(pattern, input, iterations)
+	newTime := newApproach(pattern, input, iterations)
+
+	fmt.Printf("Old approach time: %v\n", oldTime)
+	fmt.Printf("New approach time: %v\n", newTime)
+	fmt.Printf("Improvement: %.2fx faster\n", float64(oldTime)/float64(newTime))
+}

